function stopCore(){clearInterval(coreTimer);coreTimer=null;$('#coreRun').innerHTML='Run inside core <b>▶</b>'}
function renderCoreInstructionButtons(){const labels={add:'Register arithmetic',load:'Load from memory',branch:'Conditional branch'};const box=$('.core3d-instructions');box.setAttribute('aria-label',`Choose a ${coreArch.toUpperCase()} instruction`);box.innerHTML=Object.entries(CORE_PROGRAMS[coreArch]).map(([key,p])=>`<button class="${key===coreInstruction?'active':''}" data-core-instruction="${key}"><code>${p.asm}</code><span>${p.label||labels[key]}</span></button>`).join('');box.querySelectorAll('button').forEach(button=>button.onclick=()=>{coreInstruction=button.dataset.coreInstruction;resetCore()})}
function renderCore(){const program=coreProgram(),step=program.steps[coreStepIndex];const isCisc=coreArch==='cisc';$$('[data-core-arch]').forEach(b=>b.classList.toggle('active',b.dataset.coreArch===coreArch));$$('[data-core-instruction]').forEach(b=>b.classList.toggle('active',b.dataset.coreInstruction===coreInstruction));$$('.risc-core-element').forEach(x=>x.classList.toggle('hidden',isCisc));$$('.cisc-core-element').forEach(x=>x.classList.toggle('hidden',!isCisc));$('#chipModel').classList.toggle('cisc-core',isCisc);$('#core3d').classList.toggle('cisc-view',isCisc);$('#packageCode').textContent=isCisc?'EDU–C86':'EDU–R32';$('#packageTitle').textContent=isCisc?'CISC CORE':'RISC CORE';$('#packageMeta').textContent=isCisc?'VARIABLE-LENGTH · µOP · OUT-OF-ORDER':'32-BIT · 5-STAGE · LOAD/STORE';$('#dieMark').textContent=isCisc?'X86-STYLE EDUCATIONAL µOP ENGINE · NOT TO SCALE':'RISC–V STYLE EDUCATIONAL DATAPATH · NOT TO SCALE';$('#coreCaptionTitle').textContent=isCisc?'What makes it CISC?':'What makes it RISC?';$('#coreCaptionText').textContent=isCisc?'Variable-length instructions enter a sophisticated front end, where complex commands become internal micro-operations. Renaming, scheduling, execution, and in-order retirement hide that complexity from software.':'Instructions use regular fields, arithmetic stays register-to-register, and only explicit load/store instructions enter the data cache. The five pipeline stages can overlap across different instructions.';$$('[data-core-unit]').forEach(u=>{u.classList.toggle('active',u.dataset.coreUnit===step.unit);u.classList.toggle('visited',program.steps.slice(0,coreStepIndex).some(s=>s.unit===u.dataset.coreUnit))});$$('[data-core-path]').forEach(p=>p.classList.toggle('active',step.path.includes(p.dataset.corePath)));$('#corePulse').style.left=step.xy[0]+'%';$('#corePulse').style.top=step.xy[1]+'%';$('#pulseValue').textContent=step.value.split(' · ')[0];$('#corePhaseNo').textContent=String(coreStepIndex+1).padStart(2,'0');$('#corePhaseTitle').textContent=step.title;$('#corePhaseText').textContent=step.text;$('#coreBusValue').textContent=step.value;$('#coreClock').textContent=`CYCLE ${coreCycle}`;$('#coreStep').innerHTML=coreStepIndex===program.steps.length-1?'Restart pulse <b>↺</b>':'Step pulse <b>→</b>';const bitString=step.bits.padStart(32,'0').slice(-32);$('#bitLights').innerHTML=[...bitString].map(bit=>`<i class="${bit==='1'?'on':''}"></i>`).join('')}
function resetCore(){stopCore();coreStepIndex=0;coreCycle=0;renderCore()}
function stepCore(){const program=coreProgram();if(coreStepIndex===program.steps.length-1){resetCore();return}coreStepIndex++;coreCycle++;renderCore()}
function runCore(){if(coreTimer){stopCore();return}if(coreStepIndex===coreProgram().steps.length-1){coreStepIndex=0;coreCycle=0}$('#coreRun').innerHTML='Pause core <b>Ⅱ</b>';coreTimer=setInterval(()=>{if(coreStepIndex===coreProgram().steps.length-1){stopCore();return}coreStepIndex++;coreCycle++;renderCore()},900)}
$$('[data-core-arch]').forEach(button=>button.onclick=()=>{coreArch=button.dataset.coreArch;coreInstruction=coreArch==='risc'?'add':'mov';coreStepIndex=0;coreCycle=0;stopCore();renderCoreInstructionButtons();renderCore()});$('#coreStep').onclick=stepCore;$('#coreRun').onclick=runCore;$('#coreReset').onclick=resetCore;$('#coreRotation').oninput=e=>{$('#chipModel').style.setProperty('--coreRotate',e.target.value+'deg');$('#coreRotationOut').textContent=e.target.value+'°'};$('#explodeCore').onclick=()=>{$('#chipModel').classList.toggle('exploded');$('#explodeCore').classList.toggle('active');$('#explodeCore span').textContent=$('#chipModel').classList.contains('exploded')?'Join layers':'Separate layers'};
renderCoreInstructionButtons();renderCore();
